{"file_text": "@namespace sv_ec296168327d4385ba7cff46af20ca1f.Components.Pages.Settings
@using sv_ec296168327d4385ba7cff46af20ca1f.Services
@using sv_ec296168327d4385ba7cff46af20ca1f.Models
@inject ISettingsService SettingsService

<div class="settings-section">
    <h4>Security</h4>
    <hr />

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <ChangePasswordPanel OnChangePassword="HandleChangePasswordAsync" />

        <div class="mb-4">
            <h6>Two-Factor Authentication</h6>
            <div class="d-flex align-items-center gap-3">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           checked="@_twoFactorEnabled"
                           @onchange="e => _twoFactorEnabled = (bool)(e.Value ?? false)" />
                    <label class="form-check-label" for="twoFactor">Enable 2FA</label>
                </div>
                <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <small class="text-muted d-block mt-2">
                    Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </small>
            }
        </div>

        <div class="mb-4">
            <h6>Active Sessions</h6>
            <div class="table-responsive">
                <table class="table table-striped">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th></th>
                        </tr>
                    </thead>
                    <tbody>
                        @foreach (var session in _sessions)
                        {
                            var isCurrentSession = session == _sessions.FirstOrDefault();
                            <tr>
                                <td>
                                    @session.Device
                                    @if (isCurrentSession)
                                    {
                                        <span class="badge bg-info ms-1">Current</span>
                                    }
                                </td>
                                <td>@session.Location</td>
                                <td>@FormatLastActive(session.LastActive)</td>
                                <td>
                                    @if (!isCurrentSession)
                                    {
                                        <button class="btn btn-sm btn-outline-danger"
                                                @onclick="() => PromptRevoke(session)">
                                            Revoke
                                        </button>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>

        <RevokeSessionDialog Visible="_showRevokeDialog"
                             DeviceName="@(_sessionToRevoke?.Device ?? "")"
                             OnConfirm="ConfirmRevokeAsync"
                             OnCancel="CancelRevoke" />
    }
</div>

@code {
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = [];
    private bool _loading = true;

    private bool _showRevokeDialog;
    private ActiveSession? _sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        var security = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = security.TwoFactorEnabled;
        _lastPasswordChange = security.LastPasswordChange;
        _sessions = new List<ActiveSession>(security.Sessions);
        _loading = false;
    }

    private async Task HandleChangePasswordAsync((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
    }

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeDialog = true;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions.RemoveAll(s => s.Id == _sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
        _showRevokeDialog = false;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        _showRevokeDialog = false;
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}
