@namespace sv_ec296168327d4385ba7cff46af20ca1f.Components.Pages.Settings
@using sv_ec296168327d4385ba7cff46af20ca1f.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h4>Profile</h4>
    <hr />

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="avatar-preview mb-3">
            <img src="@_avatarUrl" alt="Avatar" class="rounded-circle" width="120" height="120" />
            <div class="mt-2">
                <label class="form-label">Avatar URL</label>
                <input type="text" class="form-control" @bind="_avatarUrl" />
            </div>
        </div>

        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="_displayName" />
        </div>

        <div class="mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="_email" />
        </div>

        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="3" @bind="_bio"></textarea>
        </div>

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                @(_saving ? "Saving..." : "Save Changes")
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
        </div>

        @if (_showSuccess)
        {
            <div class="alert alert-success mt-3 fade show" role="alert">
                Profile saved successfully!
            </div>
        }
    }
</div>

@code {
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    private Models.UserProfile? _savedProfile;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        ApplyProfile(profile);
        _loading = false;
    }

    private void ApplyProfile(Models.UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;
        var profile = new Models.UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _saving = false;
        _showSuccess = true;
    }

    private void Discard()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        _showSuccess = false;
    }
}

