@namespace sv_ec296168327d4385ba7cff46af20ca1f.Components.Pages.Settings
@using sv_ec296168327d4385ba7cff46af20ca1f.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h4>Appearance</h4>
    <hr />

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="mb-4">
            <h6>Theme</h6>
            @foreach (var theme in _themes)
            {
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="theme" id="theme-@theme"
                           value="@theme" checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    <label class="form-check-label" for="theme-@theme">@theme</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6>Font Size</h6>
            @foreach (var size in _fontSizes)
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="fontSize" id="fs-@size"
                           value="@size" checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    <label class="form-check-label" for="fs-@size">@size</label>
                </div>
            }
        </div>

        <div class="mb-4">
            <h6>Language</h6>
            <select class="form-select" style="max-width: 250px;"
                    @onchange="e => _language = e.Value?.ToString() ?? _language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang" selected="@(_language == lang)">@lang</option>
                }
            </select>
        </div>

        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode"
                       checked="@_compactMode"
                       @onchange="e => _compactMode = (bool)(e.Value ?? false)" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>
        </div>

        <div class="mb-4">
            <h6>Preview</h6>
            <div class="appearance-preview @PreviewClass" style="@PreviewStyle">
                <div class="preview-header">Sample Header</div>
                <p class="preview-body">
                    This is a preview of your selected appearance settings.
                    The theme, font size, and compact mode are reflected here.
                </p>
                <button class="btn btn-sm @PreviewButtonClass">Sample Button</button>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @(_saving ? "Saving..." : "Save")
        </button>

        @if (_showSuccess)
        {
            <div class="alert alert-success mt-3 fade show" role="alert">
                Appearance settings saved!
            </div>
        }
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string PreviewClass => _theme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string PreviewStyle
    {
        get
        {
            var size = _fontSize switch
            {
                "Small" => "0.85rem",
                "Large" => "1.2rem",
                _ => "1rem"
            };
            var padding = _compactMode ? "0.5rem" : "1rem";
            return $"font-size: {size}; padding: {padding};";
        }
    }

    private string PreviewButtonClass => _theme == "Dark" ? "btn-light" : "btn-primary";

    private async Task SaveAsync()
    {
        _saving = true;
        _showSuccess = false;
        await SettingsService.SaveAppearanceAsync(
            new Models.AppearanceSettings(_theme, _fontSize, _language, _compactMode));
        _saving = false;
        _showSuccess = true;
    }
}

